using System;using System.IO;using System.Linq;using System.Collections.Generic;
namespace DoomSNESed {
    public static class GraphicPackingTests {
        static void Check(bool value,string message){Bin.Require(value,"Graphic packing: "+message);}
        public static void Run(string path,string output){string resources=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"editor-data"),folder=Path.Combine(output,"packing-017");Directory.CreateDirectory(folder);var rom=new Rom(path,resources);
            Check(NativeColumnCodec.Encode(new byte[]{4,0,0,0,0},true).SequenceEqual(new byte[]{4,0,0}),"transparent sprite tops end without redundant runs");Check(NativeColumnCodec.Encode(new byte[]{7,7,8,8},false).Length==4,"short wall repeats use minimum packets");
            var frame=GraphicsAssets.Describe(rom.Bytes,true,39);rom.Project.Graphics.Add(new GraphicReplacement{Sprite=true,Id=39,Width=frame.Width,Height=frame.Height,Pixels=GraphicsAssets.Decode(rom.Bytes,frame)});var unchanged=rom.Compile();Check(rom.Budget.Graphics==0&&rom.Budget.Music==0&&rom.Budget.GraphicsReused>0,"unchanged sprite columns reuse their data without moving audio");Check(AudioRom.ChunkAddress(unchanged)==AudioRom.ChunkAddress(rom.Bytes),"graphics reuse preserves the audio table");
            rom=new Rom(path,resources);rom.Project.Maps[0]=rom.MakeRoom(0,512,512);rom.Project.Maps[0].EditGeometry=true;rom.Project.CampaignSlots=new[]{0};var screen=new GraphicReplacement{Screen=2,Width=256,Height=224,Pixels=new byte[256*224],Palette=Enumerable.Range(0,16).Select(i=>i*2114).ToArray()};for(int y=0;y<224;y++)for(int x=0;x<256;x++){int px=(x/8%2)!=0?7-x%8:x%8,py=(y/8%2)!=0?7-y%8:y%8;screen.Pixels[y*256+x]=(byte)((px+py*3)%16);}rom.Project.Graphics.Add(screen);
            var font=HudAssets.All().First(a=>a.Screen==6);byte[] fontPixels=HudAssets.Pixels(HudAssets.Data(rom.Bytes,6),font.Width,font.Height);fontPixels[0]=(byte)((fontPixels[0]+1)%16);rom.Project.Graphics.Add(new GraphicReplacement{Screen=6,Width=font.Width,Height=font.Height,Pixels=fontPixels});byte[] image=rom.Compile();
            int table=ScreenAssets.Tables[2],defs=GraphicsAssets.Address(image,table+2);Check(((Bin.U16(image,table)&0x4000)!=0?Bin.U16(image,table+10):Bin.U16(image,defs+2))==32,"screen atlas shares horizontally and vertically flipped tiles");Check(rom.Budget.Graphics<3168,"simple screen/font store compressed native bytes");
            using(var actual=ScreenAssets.OriginalImage(image,2))using(var expected=ScreenAssets.Preview(screen))for(int y=0;y<224;y++)for(int x=0;x<256;x++)Check(actual.GetPixel(x,y)==expected.GetPixel(x,y),"flipped compressed screen pixel parity");Check(HudAssets.Data(image,6).SequenceEqual(HudAssets.Tiles(rom.Project.Graphics.Last())),"compressed font round trip");
            File.WriteAllBytes(Path.Combine(folder,"compressed-native.sfc"),image);rom.SavePatch(Path.Combine(folder,"compressed-native.dse"),image);rom.SaveProject(Path.Combine(folder,"compressed-native.sned"));
            foreach(string name in new[]{"KICK","iconofshit"}){string source=Path.Combine(Path.GetDirectoryName(path),"testfiles",name+".sfc");if(!File.Exists(source))continue;var original=new Rom(path,resources);var edited=new Rom(source,resources);for(int sprite=0;sprite<2;sprite++)foreach(int id in sprite!=0?Enumerable.Range(0,232):Enumerable.Range(2,61).Select(i=>i*2)){var a=GraphicsAssets.Describe(edited.Bytes,sprite!=0,id);var pixels=GraphicsAssets.Decode(edited.Bytes,a);if(!pixels.SequenceEqual(GraphicsAssets.Decode(original.Bytes,GraphicsAssets.Describe(original.Bytes,a.Sprite,id))))edited.Project.Graphics.Add(new GraphicReplacement{Sprite=a.Sprite,Id=id,Width=a.Width,Height=a.Height,Pixels=pixels});}edited.Project.RetailAssets=true;edited.Project.CompactAssets=true;var packed=edited.Compile();Check(packed.Length==0x200000,"user ROM stays 2 MiB");foreach(var a in edited.Project.Graphics)Check(GraphicsAssets.Decode(packed,GraphicsAssets.Describe(packed,a.Sprite,a.Id)).SequenceEqual(a.Pixels),"user artwork lossless round trip");Console.WriteLine(name+" new="+edited.Budget.Graphics+" reclaimed="+edited.Budget.GraphicsReclaimed+" reused="+edited.Budget.GraphicsReused+" audioMoves="+edited.Budget.Music);Check(edited.Budget.Music==0,"fitting user columns do not trigger audio relocation");File.WriteAllBytes(Path.Combine(folder,name+"-packed.sfc"),packed);edited.SavePatch(Path.Combine(folder,name+"-packed.dse"),packed);edited.SaveProject(Path.Combine(folder,name+"-packed.sned"));}
            File.WriteAllText(Path.Combine(output,"graphic-packing-017-results.txt"),"PASS optimal short runs, trimmed sprite transparency, existing-column reuse, no unnecessary audio moves, compressed/flipped screen atlas pixel parity, compressed font, user ROM lossless packing and 2 MiB output.\r\n");
        }
    }
}


